CustomField.formula:
IF(
  CONTAINS(ToAddress, $Label.AMFS_Channel_CS), "CS",
  IF(
    CONTAINS(ToAddress, $Label.AMFS_Channel_OH), "OH",
    IF(
      CONTAINS(ToAddress, $Label.AMFS_Channel_PBC), "PBC",
      IF(
        CONTAINS(ToAddress, $Label.AMFS_Channel_Syariah), "Syariah",
        IF(
          CONTAINS(FromAddress, $Label.AMFS_Channel_CS), "CS",
          IF(
            CONTAINS(FromAddress, $Label.AMFS_Channel_OH), "OH",
            IF(
              CONTAINS(FromAddress, $Label.AMFS_Channel_PBC), "PBC",
              IF(
                CONTAINS(FromAddress, $Label.AMFS_Channel_Syariah), "Syariah",
                NULL
              )
            )
          )
        )
      )
    )
  )
)
